  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// JWT Secret
const JWT_SECRET = process.env.JWT_SECRET;
if (!JWT_SECRET) {
  throw new Error('JWT_SECRET environment variable is required');
}

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn(`Unauthorized access attempt from ${req.ip}`);
    return res.status(401).json({ error: 'No token provided' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid token from ${req.ip}`);
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
}

// Health check (public)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Users endpoint (protected)
app.get('/users', 
  authenticateToken,
  query('id').optional().isInt().toInt(),
  query('name').optional().trim().escape(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn(`Validation error from ${req.ip}:`, errors.array());
      return res.status(400).json({ errors: errors.array() });
    }

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// Error handler
app.use((err, req, res, next) => {
  logger.error(err);
  const isDevelopment = process.env.NODE_ENV === 'development';
  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal Server Error'
  });
});

// Start server with HTTPS
const options = {
  key: fs.readFileSync(process.env.SSL_KEY || './server.key'),
  cert: fs.readFileSync(process.env.SSL_CERT || './server.cert')
};

https.createServer(options, app).listen(3000, () => {
  console.log('Server running securely on port 3000');
  logger.info('Server started on port 3000');
});

module.exports = app;
```

