};

// Audit logging helper
const auditLog = (userId, action, resource, status) => {
  const timestamp = new Date().toISOString();
  console.log(`[AUDIT] ${timestamp} - User: ${userId}, Action: ${action}, Resource: ${resource}, Status: ${status}`);
  // In production, write to secure audit log system
};

app.get('/users', authMiddleware, authorizationMiddleware('admin'), (req, res) => {
  auditLog(req.user.id, 'READ', 'users', 'SUCCESS');
  res.json([
