### 4. **Injection Vulnerabilities (OWASP A03:2021 - Injection)**

**Severity:** HIGH (Potential)

#### Issues:
- **No input validation:** Query parameters not validated or sanitized
- **Vulnerable to NoSQL/SQL injection:** If extended to database queries
- **No output encoding:** Response data not validated

#### Current Code:
```javascript
app.get('/users', (req, res) => {
  // No validation of req.query or req.params
  res.json([...]);
});
```

#### Vulnerable Example (Extended Code):
```javascript
// VULNERABLE - DO NOT USE
app.get('/user/:id', (req, res) => {
  // Direct user input in query
  db.query(`SELECT * FROM users WHERE id = ${req.params.id}`, (err, result) => {
    res.json(result);
  });
});
// Attacker: GET /user/1; DROP TABLE users;--
```

#### Recommended Fix:
```javascript
const validator = require('validator');
const { query, param, validationResult } = require('express-validator');

// Input validation middleware
const validateInput = [
  param('id').isInt().toInt(),
  query('search').optional().trim().escape(),
];

app.get('/user/:id', validateInput, (req, res) => {
  const errors = validationResult(req);

  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Use parameterized queries (safe against injection)
  const id = req.params.id;
  db.query('SELECT * FROM users WHERE id = ?', [id], (err, result) => {
    if (err) {
      console.error('Database error:', err);
      return res.status(500).json({ error: 'Internal server error' });
    }
    res.json(result);
  });
});
```

