  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400, // 24 hours
};

app.use(cors(corsOptions));

// Disable powered-by header
app.disable('x-powered-by');
```

---

### 🟡 MEDIUM: A09:2021 - Using Components with Known Vulnerabilities

#### Issue 7: No Logging or Monitoring
**Severity:** MEDIUM (CVSS 6.5)

**Location:** Entire application

**Problem:**
- No security event logging
- No request logging for audit trails
- Cannot detect or respond to attacks
- No monitoring of authentication failures

**Recommendation:**

```javascript
const express = require('express');
const morgan = require('morgan');
const winston = require('winston');
const app = express();

// Setup Winston logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// HTTP request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim()),
  },
}));

// Security event logging middleware
const logSecurityEvent = (event, details) => {
  logger.warn({
    timestamp: new Date().toISOString(),
    event,
    ...details,
  });
};

// Usage in authentication
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    logSecurityEvent('AUTH_FAILED', {
      ip: req.ip,
      reason: 'Missing token',
    });
    return res.status(401).json({ error: 'Unauthorized' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    logSecurityEvent('AUTH_SUCCESS', {
      userId: decoded.id,
      ip: req.ip,
    });
    req.userId = decoded.id;
    next();
  } catch (error) {
    logSecurityEvent('AUTH_FAILED', {
      ip: req.ip,
      reason: 'Invalid token',
      error: error.message,
    });
    return res.status(403).json({ error: 'Forbidden' });
  }
};
```

