# Security Audit Report: app.js

**Date:** May 23, 2026  
**Application:** Express.js Simple Server  
**Risk Level:** Medium  

---

## Executive Summary

The application is a minimal Express.js server with basic endpoints. While the current functionality is relatively simple, the application has **several critical security gaps** that need to be addressed before production deployment. The main concerns involve missing authentication/authorization, lack of input validation, missing security headers, and inadequate error handling.

---

## Findings

### 🔴 CRITICAL ISSUES

#### 1. **Missing Authentication & Authorization (OWASP #01: Broken Access Control)**

**Severity:** CRITICAL  
**Location:** Lines 11-16 (`/users` endpoint)

**Issue:**
The `/users` endpoint exposes sensitive user data (names and email addresses) without any authentication mechanism. Any unauthenticated user can access this endpoint.

```javascript
// VULNERABLE: No authentication check
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Risk:** Unauthorized access to sensitive personal data (PII), data exposure, privacy violations.

**Recommendation:**

```javascript
// SECURE: Add authentication middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }

  try {
    const decoded = verifyToken(token); // Implement token verification
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({ error: 'Invalid token' });
  }
};

app.get('/users', authenticate, (req, res) => {
  // Add authorization check
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

#### 2. **Missing Security Headers (OWASP #05: Security Misconfiguration)**

**Severity:** HIGH  
**Location:** Global middleware (missing)

**Issue:**
The application doesn't set critical security headers that protect against common attacks:
- No Content Security Policy (CSP)
- No X-Frame-Options (clickjacking protection)
- No X-Content-Type-Options (MIME sniffing protection)
- No Strict-Transport-Security (HSTS)
- No X-XSS-Protection

**Risk:** Vulnerability to clickjacking, MIME sniffing, XSS attacks, and man-in-the-middle attacks.

**Recommendation:**

```javascript
const express = require('express');
const helmet = require('helmet');
const app = express();

// Apply security headers using helmet middleware
app.use(helmet());

// Additional custom headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  res.setHeader('Content-Security-Policy', "default-src 'self'");
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});
```

**Installation:**
```bash
npm install helmet
```

---

### 🟠 HIGH PRIORITY ISSUES

#### 3. **No Input Validation or Sanitization**

**Severity:** HIGH  
**Location:** All endpoints

**Issue:**
While the current endpoints don't explicitly accept user input, the application doesn't validate request data. If query parameters or body data were added in the future, they could be vulnerable to injection attacks.

**Current Risk:** Not immediately exploitable, but infrastructure missing for safe input handling.

**Recommendation:**

```javascript
const express = require('express');
const { query, validationResult } = require('express-validator');
const app = express();

app.use(express.json()); // Parse JSON with size limits
app.use(express.urlencoded({ limit: '10kb', extended: true })); // Prevent large payloads

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// Example: Validate query parameters
app.get('/users', 
  query('id').optional().isInt().toInt(),
  query('limit').optional().isInt({ max: 100 }).toInt(),
  validateRequest,
  authenticate,
  (req, res) => {
    // Safe to use req.query.id and req.query.limit
    res.json([...]);
  }
);
```

---

#### 4. **Inadequate Error Handling (OWASP #03: Injection / #09: Insufficient Logging)**

**Severity:** HIGH  
**Location:** Entire application

**Issue:**
No global error handling middleware. Unhandled errors could leak sensitive information or crash the server.

```javascript
// VULNERABLE: No error handler
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
// Unhandled errors will crash the app or leak stack traces
```

**Risk:** Information disclosure, denial of service, poor security visibility.

**Recommendation:**

```javascript
// Global error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// Handle 404s
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Graceful error handling on server
app.listen(3000, () => {
  console.log('Server running on port 3000');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});
```

---

#### 5. **No Rate Limiting (OWASP #05: Security Misconfiguration / #07: Identification and Authentication Failures)**

**Severity:** HIGH  
**Location:** All endpoints

**Issue:**
The application has no rate limiting protection, making it vulnerable to brute force attacks, DoS attacks, and API abuse.

```javascript
// VULNERABLE: No rate limiting
app.get('/users', (req, res) => {
  // Can be hammered with unlimited requests
});
```

**Risk:** Denial of service, brute force attacks, API abuse.

**Recommendation:**

```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

// Stricter limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true, // Don't count successful requests
});

app.use(limiter); // Apply to all routes
app.post('/login', authLimiter, (req, res) => {
  // Login endpoint with stricter rate limiting
});
```

**Installation:**
```bash
npm install express-rate-limit
```

---

### 🟡 MEDIUM PRIORITY ISSUES

#### 6. **No Request Size Limits (OWASP #08: Software and Data Integrity Failures)**

**Severity:** MEDIUM  
**Location:** Lines 4-5 (middleware setup)

**Issue:**
Express doesn't have default request size limits, allowing potential buffer overflow or DoS via large payloads.

**Current Code:**
```javascript
const express = require('express');
const app = express();
// No size limits configured
```

**Recommendation:**

```javascript
const express = require('express');
const app = express();

// Set reasonable size limits
app.use(express.json({ limit: '1kb' })); // Adjust based on your needs
app.use(express.urlencoded({ limit: '1kb', extended: true }));

// For file uploads, use dedicated middleware with limits
const multer = require('multer');
const upload = multer({ 
  limits: { fileSize: 5 * 1024 * 1024 } // 5MB max
});
```

---

#### 7. **Missing CORS Configuration (OWASP #01: Broken Access Control)**

**Severity:** MEDIUM  
**Location:** Global middleware (missing)

**Issue:**
No CORS (Cross-Origin Resource Sharing) configuration. This could either be overly permissive or cause issues with legitimate clients.

**Recommendation:**

```javascript
const cors = require('cors');

// Restrictive CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com'],
  methods: ['GET', 'POST'],
  credentials: true,
  optionsSuccessStatus: 200,
  maxAge: 86400
};

app.use(cors(corsOptions));

// Or use default restrictive settings
// app.use(cors());
```

**Installation:**
```bash
npm install cors
```

---

#### 8. **Hardcoded User Data (OWASP #01: Broken Access Control / #05: Security Misconfiguration)**

**Severity:** MEDIUM  
**Location:** Lines 12-15

**Issue:**
User data is hardcoded directly in the application. This is problematic for several reasons:
- Not scalable
- Can't be updated without code changes
- Could accidentally expose sensitive data
- Version control exposure

```javascript
// VULNERABLE: Hardcoded data
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:**

```javascript
// Use a database
const db = require('./database'); // Your DB connection

app.get('/users', authenticate, async (req, res, next) => {
  try {
    const users = await db.query('SELECT id, name, email FROM users LIMIT 100');
    res.json(users);
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Or use environment-based configuration
const USERS = JSON.parse(process.env.USERS_DATA || '[]');
```

---

#### 9. **No HTTPS Enforcement (OWASP #02: Cryptographic Failures)**

**Severity:** MEDIUM  
**Location:** Entire application

**Issue:**
The application doesn't enforce HTTPS. All data in transit is unencrypted.

**Recommendation:**

```javascript
app.use((req, res, next) => {
  // Redirect HTTP to HTTPS in production
  if (process.env.NODE_ENV === 'production' && req.header('x-forwarded-proto') !== 'https') {
    return res.redirect(301, `https://${req.header('host')}${req.url}`);
  }
  next();
});
```

**Or configure at the infrastructure level:**
- Use a reverse proxy (nginx, Apache) to enforce HTTPS
- Use environment variables to configure HTTPS certificates
- Use services like CloudFlare or AWS CloudFront

---

#### 10. **No Logging/Monitoring (OWASP #09: Insufficient Logging & Monitoring)**

**Severity:** MEDIUM  
**Location:** Entire application

**Issue:**
No request logging or security event monitoring. Can't detect attacks or debug issues.

**Recommendation:**

```javascript
const morgan = require('morgan');
const winston = require('winston');

// HTTP request logging
app.use(morgan('combined'));

// Security event logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Log security events
app.use((req, res, next) => {
  logger.info(`${req.method} ${req.path} from ${req.ip}`);
  next();
});
```

**Installation:**
```bash
npm install morgan winston
```

