441	// ✅ Validate query parameters
442	app.get('/users',
443	  query('page').optional().isInt({ min: 1 }).toInt(),
444	  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
445	  (req, res) => {
446	    const errors = validationResult(req);
447	    if (!errors.isEmpty()) {
448	      return res.status(400).json({ errors: errors.array() });
449	    }
450	    // Process with validated parameters
451	  }
452	);
453	
454	// ✅ Validate POST body
455	app.post('/users',
456	  body('name').trim().isLength({ min: 1, max: 100 }),
457	  body('email').isEmail().normalizeEmail(),
