541	  max: 100, // limit each IP to 100 requests per windowMs
542	  message: 'Too many requests from this IP',
543	  standardHeaders: true,
544	  legacyHeaders: false,
545	});
546	
547	app.use(limiter);
548	
549	// ✅ Stricter limit for login attempts
