656	// ✅ Health check (no auth needed)
657	app.get('/health', (req, res) => {
658	  res.json({ status: 'ok', timestamp: new Date().toISOString() });
659	});
660	
661	// ✅ Protected endpoints with authentication
662	app.get('/users', authenticateToken, (req, res) => {
663	  // Only authenticated users
664	  res.json([
665	    { id: 1, name: 'Alice', email: 'alice@example.com' },
666	    { id: 2, name: 'Bob', email: 'bob@example.com' },
667	  ]);
668	});
669	
670	// ✅ Error handling
671	app.use((err, req, res, next) => {
672	  logger.error('Error:', err);
673	  res.status(err.status || 500).json({ error: 'Internal Server Error' });
674	});
675	
676	// ✅ 404 handling
677	app.use((req, res) => {
678	  res.status(404).json({ error: 'Not found' });
679	});
680	
681	const PORT = process.env.PORT || 3000;
682	app.listen(PORT, () => {
