  query('name').optional().trim().escape().isLength({ max: 100 }),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by validated parameters
    let result = users;
    if (req.query.id) {
      result = result.filter(u => u.id === req.query.id);
