### 4. **Missing Input Validation & Injection Attacks**

#### Issue: No Input Sanitization or Validation
**Severity:** HIGH

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  // Query parameters are not validated
  // This is vulnerable to injection if data is used in queries
});
```

**Potential Attack Scenario - SQL Injection:**
```bash
# If filtering were implemented without validation:
curl "http://localhost:3000/users?id=1 OR 1=1--"
# Would bypass filtering and return all users
```

**Potential Attack Scenario - NoSQL Injection:**
```bash
curl "http://localhost:3000/users?email[%24gt]=''"
# Could bypass authentication or return unexpected data
```

**Remediation:**
```javascript
const express = require('express');
const { body, query, validationResult } = require('express-validator');
const app = express();

// ✓ SECURE: Input validation middleware
const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  query('email')
    .optional()
    .isEmail()
    .withMessage('Invalid email format')
];

app.get('/users', validateUserQuery, (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { id, email } = req.query;

  // Use parameterized queries to prevent injection
  let query = 'SELECT * FROM users WHERE 1=1';
  let params = [];

  if (id) {
    query += ' AND id = $' + (params.length + 1);
    params.push(id);
  }

  if (email) {
    query += ' AND email = $' + (params.length + 1);
    params.push(email);
  }

  // Execute with parameterized query
  db.query(query, params, (err, result) => {
    if (err) {
      return res.status(500).json({ error: 'Database error' });
    }
    res.json(result.rows);
  });
});
```

