  }
}));

// Security event logging
app.use((req, res, next) => {
  res.on('finish', () => {
    if (res.statusCode >= 400) {
      logger.warn({
        timestamp: new Date(),
        ip: req.ip,
        method: req.method,
        path: req.path,
