## 🟢 RECOMMENDATIONS FOR SECURE PRODUCTION DEPLOYMENT

### 1. **Implement a Comprehensive Security Framework**
```javascript
// secure-app.js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { body, query, validationResult } = require('express-validator');
const winston = require('winston');
const morgan = require('morgan');

const app = express();

// Logger setup
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// Security middleware stack
app.use(helmet());
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});
app.use(limiter);

// Request logging
app.use(morgan('combined', {
  stream: { write: (msg) => logger.info(msg.trim()) }
}));

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    logger.warn({ action: 'unauthorized_access', path: req.path, ip: req.ip });
    return res.status(401).json({ error: 'Unauthorized' });
  }

  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    logger.warn({ action: 'invalid_token', path: req.path, ip: req.ip });
    return res.status(403).json({ error: 'Invalid token' });
  }
};

// Health check - protected
app.get('/health', authenticateToken, (req, res) => {
  res.json({ status: 'ok' });
});

// Users endpoint - protected with input validation
app.get('/users',
  authenticateToken,
  query('id').optional().isInt({ min: 1 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Return only current user's data
    res.json([{
      id: req.user.id,
      name: req.user.name
    }]);
  }
);

app.listen(process.env.PORT || 3000, () => {
  logger.info('Server started');
});

module.exports = app;
```

