// SECURE VERSION - Production-ready Express app with security best practices
// This is a REFERENCE IMPLEMENTATION showing how to properly secure the application

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const winston = require('winston');

const app = express();

// ============================================================================
// 1. LOGGING SETUP
// ============================================================================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================================================
// 2. SECURITY HEADERS
// ============================================================================
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
  },
}));

// Strict transport security
app.use((req, res, next) => {
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});

// ============================================================================
// 3. ENFORCE HTTPS IN PRODUCTION
// ============================================================================
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    logger.warn({
      message: 'Attempted non-HTTPS connection',
      ip: req.ip,
      path: req.path,
    });
    return res.redirect(`https://${req.header('host')}${req.url}`);
  }
  next();
});

// ============================================================================
// 4. CORS CONFIGURATION
// ============================================================================
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Total-Count'],
  maxAge: 86400,
};

app.use(cors(corsOptions));

// ============================================================================
// 5. BODY PARSER WITH LIMITS
// ============================================================================
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// Validate Content-Type
app.use((req, res, next) => {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    const contentType = req.get('Content-Type');
    if (contentType && !['application/json', 'application/x-www-form-urlencoded'].includes(contentType)) {
      logger.warn({
        message: 'Invalid Content-Type',
        contentType,
        ip: req.ip,
        path: req.path,
      });
      return res.status(415).json({ error: 'Unsupported Media Type' });
    }
  }
  next();
});

// ============================================================================
// 6. REQUEST LOGGING
// ============================================================================
const morganStream = {
  write: (message) => logger.info(message.trim()),
};

app.use(morgan(':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent"', { stream: morganStream }));

// ============================================================================
// 7. RATE LIMITING
// ============================================================================
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.ip === '127.0.0.1', // Skip localhost for development
  keyGenerator: (req) => req.ip,
  handler: (req, res) => {
    logger.warn({
      message: 'Rate limit exceeded',
      ip: req.ip,
      path: req.path,
    });
    res.status(429).json({ error: 'Too many requests' });
  },
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many authentication attempts',
});

app.use(generalLimiter);

// ============================================================================
// 8. AUTHENTICATION MIDDLEWARE
// ============================================================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn({
      message: 'Missing authentication token',
      ip: req.ip,
      path: req.path,
    });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'dev-secret', (err, user) => {
    if (err) {
      logger.warn({
        message: 'Invalid or expired token',
        ip: req.ip,
        error: err.message,
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============================================================================
// 9. AUTHORIZATION MIDDLEWARE
// ============================================================================
const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user || !req.user.roles) {
      logger.warn({
        message: 'Unauthorized access attempt',
        ip: req.ip,
        path: req.path,
        user: req.user?.id,
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    const hasRole = roles.some(role => req.user.roles.includes(role));
    if (!hasRole) {
      logger.warn({
        message: 'Access denied - insufficient role',
        ip: req.ip,
        path: req.path,
        user: req.user?.id,
        requiredRoles: roles,
        userRoles: req.user.roles,
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// ============================================================================
// 10. PUBLIC ENDPOINTS
// ============================================================================

// Health check (no auth required, minimal info)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// ============================================================================
// 11. PROTECTED ENDPOINTS WITH INPUT VALIDATION
// ============================================================================

// Get all users (requires authentication and admin role)
app.get('/users',
  authenticateToken,
  authorize('admin'),
  (req, res) => {
    // Log access to sensitive endpoint
    logger.info({
      message: 'Users list accessed',
      user: req.user.id,
      ip: req.ip,
    });

    // Return user list
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    res.json({
      data: users,
      count: users.length,
    });
  }
);

// Get specific user with validation
app.get('/users/:id',
  authenticateToken,
  authorize('admin', 'user'),
  [
    query('id').optional().isInt(),
  ],
  (req, res) => {
    // Check input validation
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({
        message: 'Invalid input',
        errors: errors.array(),
        user: req.user.id,
      });
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = parseInt(req.params.id, 10);

    // Authorization check: users can only see their own data (unless admin)
    if (!req.user.roles.includes('admin') && req.user.id !== userId) {
      logger.warn({
        message: 'Unauthorized user access attempt',
        user: req.user.id,
        targetUser: userId,
        ip: req.ip,
      });
      return res.status(403).json({ error: 'Cannot access other users\' data' });
    }

    // Simulated user lookup
    const user = userId === 1
      ? { id: 1, name: 'Alice', email: 'alice@example.com' }
      : userId === 2
      ? { id: 2, name: 'Bob', email: 'bob@example.com' }
      : null;

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  }
);

// ============================================================================
// 12. ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  logger.warn({
    message: '404 Not Found',
    method: req.method,
    path: req.path,
    ip: req.ip,
  });
  res.status(404).json({ error: 'Not found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error({
    message: 'Unhandled error',
    error: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
    ip: req.ip,
  });

  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================================================
// 13. SERVER START
// ============================================================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info({
    message: 'Server started',
    port: PORT,
    environment: NODE_ENV,
    timestamp: new Date().toISOString(),
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

