### 3. **HIGH: Missing Authentication and Authorization**
**Category:** OWASP A01:2021 – Broken Access Control  
**Severity:** HIGH

**Issue:**
Endpoints are completely open without any authentication mechanism:

```javascript
app.get('/users', (req, res) => {
  res.json([...]);  // Anyone can access this
});
```

**Risks:**
- Any client can query sensitive user data
- No rate limiting per user
- No audit trail of who accessed data
- No role-based access control (RBAC)

**Recommendations:**
```javascript
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Apply authentication to protected endpoints
app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Public health check (no auth required)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});
```

