## Secure Production Setup

Here's a recommended production-ready configuration:

```javascript
const express = require('express');
const https = require('https');
const fs = require('fs');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const cors = require('cors');

const app = express();

// ============ LOGGING ============
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// ============ SECURITY HEADERS ============
app.use(helmet());

// ============ CORS ============
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://example.com'],
  credentials: true,
}));

// ============ BODY PARSING ============
app.use(express.json({ limit: '1mb' }));

// ============ RATE LIMITING ============
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests, please try again later',
});
app.use(limiter);

// ============ REQUEST LOGGING ============
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
  });
  next();
});

// ============ AUTHENTICATION ============
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn('Invalid token attempt', { token: token?.substring(0, 10) });
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// ============ PUBLIC ENDPOINTS ============
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ============ PROTECTED ENDPOINTS ============
const validateUserQuery = [
  query('id').optional().isInt({ min: 1 }),
  query('name').optional().isLength({ max: 100 }).trim().escape(),
];

app.get('/users', authenticateToken, validateUserQuery, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  logger.info('Users endpoint accessed', { userId: req.user?.id });
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ============ ERROR HANDLING ============
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    message: err.message,
    stack: err.stack,
    path: req.path,
  });

  const isDev = process.env.NODE_ENV === 'development';
  res.status(err.statusCode || 500).json({
    error: isDev ? err.message : 'Internal server error',
  });
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ============ HTTPS SERVER ============
if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH),
  };
  https.createServer(options, app).listen(3000, () => {
    logger.info('Secure server started on port 3000');
  });
} else {
  app.listen(3000, () => {
    logger.warn('Running in development mode without HTTPS');
  });
}

module.exports = app;
```

